import {V,Q,part,ports,emptyModel,add,solve,targets,definition} from './engine.js';
import {makeLayer,makeGroup} from './editor-state.js';
import {gearDemo} from './gears.js';
export function towerModel(){const m=emptyModel('Four-storey braced tower'),rows=[];const node=(pos,side)=>{const a=part('c-blue',pos,Q().setFromAxisAngle(V([0,1,0]),side<0?Math.PI:0).toArray());m.parts.push(a);return[a,add(m,solve(m,'c-purple',targets(m,'c-purple','interlock').find(t=>t.partId===a.id),'interlock'))];};
 const join=(a,b,type)=>{const dir=V(b[0].pos).sub(V(a[0].pos)).normalize(),t=a.flatMap(ports).find(t=>t.kind==='slot'&&V(t.dir).dot(dir)>.999),other=b.flatMap(ports).find(t=>t.kind==='slot'&&V(t.dir).dot(dir)<-.999);if(!t||!other)throw Error('Missing tower socket');const r=add(m,solve(m,type,targets(m,type,'end').find(x=>x.partId===t.partId&&x.key===t.key),'end'));if(V(ports(r)[1].pos).distanceTo(V(other.pos))>.01)throw Error('Tower span mismatch');return r;};
 for(let y=0;y<=4;y++){const before=m.parts.length,row=[];for(const side of[-1,1])row.push([-150,0,150].map(x=>node([x,20+y*150,side*75],side)));rows.push(row);for(let side=0;side<2;side++)for(let x=0;x<2;x++)join(row[side][x],row[side][x+1],'r-red');for(let x=0;x<3;x++)join(row[0][x],row[1][x],'r-red');if(y)for(let side=0;side<2;side++){for(let x=0;x<3;x++)join(rows[y-1][side][x],row[side][x],'r-red');for(let x=0;x<2;x++)join(rows[y-1][side][x+y%2],row[side][x+1-y%2],'r-gray');}const ids=m.parts.slice(before).map(p=>p.id);makeLayer(m,ids,y?'Storey '+y:'Base');makeGroup(m,ids,y?'Storey '+y:'Base frame');}return m;}
export function compoundGearModel(){const m=gearDemo();m.name='Compound gearbox · two stages';const firstIds=m.parts.map(p=>p.id),shaft=m.parts.find(p=>p.type==='r-red'),attach=(type,host,mode,options={})=>add(m,solve(m,type,targets(m,type,mode).find(t=>t.partId===host.id),mode,options));
 const clip=attach('k-tan',shaft,'through',{offset:22}),gear=attach('g-red34',clip,'keyed');m.links.push({a:shaft.id,ap:'shaft',b:gear.id,bp:'hole',mode:'through',offset:V(gear.pos).sub(V(shaft.pos)).dot(V([1,0,0]).applyQuaternion(Q(shaft.quat)))});
 const driven=attach('g-gray14',gear,'mesh'),output=attach('r-red',driven,'through');for(const offset of[-45,45])attach('c-gray',output,'through',{offset,roll:90});
 // A keyed indicator makes the second-stage output visible during playback.
 const outputClip=attach('k-tan',output,'through',{offset:51}),hub=attach('c-white',outputClip,'keyed');m.links.push({a:output.id,ap:'shaft',b:hub.id,bp:'hole',mode:'through',offset:57.35});for(const key of['slot0','slot2','slot4','slot6'])add(m,solve(m,'r-green',targets(m,'r-green','end').find(t=>t.partId===hub.id&&t.key===key),'end'));
 makeLayer(m,firstIds,'Input stage');makeGroup(m,firstIds,'Motor and first mesh');const rest=m.parts.filter(p=>!firstIds.includes(p.id)).map(p=>p.id);makeLayer(m,rest,'Output stage');makeGroup(m,rest,'Second mesh and indicator');return m;
}
export function repeatableSquare(){const m=emptyModel('Repeatable square · 75 × 75 mm'),nodes=[[0,30,0],[75,30,0],[75,105,0],[0,105,0]].map((pos,i)=>part('c-white',pos,Q().setFromAxisAngle(V([0,0,1]),i*Math.PI/2).toArray()));m.parts.push(...nodes);for(let i=0;i<4;i++){const direction=V(nodes[(i+1)%4].pos).sub(V(nodes[i].pos)).normalize(),target=targets(m,'r-blue','end').find(t=>t.partId===nodes[i].id&&V(t.dir).dot(direction)>.999);add(m,solve(m,'r-blue',target,'end'));}makeGroup(m,m.parts.map(p=>p.id),'Square module');return m;}
